def remove_lines(lines: Sequence[str], start: int, end: int) -> List[str]:
    """Drop ``lines[start:end]``, keeping the enclosing block non-empty.

    Deleting the only statement of an indented block would leave the header
    dangling, so a ``pass`` takes its place in that case.

    Args:
        lines: All lines of the program.
        start: First line to remove.
        end: One past the last line to remove.

    Returns:
        The remaining lines.
    """
    indent = indent_width(lines[start])
    remaining = list(lines[:start]) + list(lines[end:])
    if indent == 0 or _has_sibling(lines, start, end, indent):
        return remaining
    remaining.insert(start, ' ' * indent + 'pass')
    return remaining


def _has_sibling(lines: Sequence[str], start: int, end: int,
                 indent: int) -> bool:
    """Whether the block around ``lines[start:end]`` keeps another statement."""
    for index in range(start - 1, -1, -1):
        if is_blank(lines[index]):
            continue
        if indent_width(lines[index]) < indent:
            break
        return True
    for index in range(end, len(lines)):
        if is_blank(lines[index]):
            continue
        if indent_width(lines[index]) < indent:
            break
        return True
    return False

